// std::unique_ptr: Exclusive, move-only ownership
auto u_ptr_res = std::make_unique<int>(42);

// Ownership transfer required (no copy)
auto u_ptr_new = std::move(u_ptr_res);

// Access value and raw pointer
*u_ptr_new = 100;
int* raw_p = u_ptr_new.get();

// Unique_ptr with a Custom Deleter
struct FileCloser { void operator()(FILE* f) const { fclose(f); } };
std::unique_ptr<FILE, FileCloser>
    log_file(fopen("log.txt", "w"));

// ------------------------------------------

// std::shared_ptr: Reference counted, shared ownership
auto s_ptr_A = std::make_shared<std::string>("Shared");

// Copying is allowed (Increments reference count)
auto s_ptr_B = s_ptr_A;

// Check how many pointers share ownership
int count = s_ptr_A.use_count(); // 2

// Access value
if (s_ptr_B) { s_ptr_B->append(" Data"); }

// ------------------------------------------

// std::weak_ptr: Non-owning observer (Breaks cycles)
auto s_ptr_C = std::make_shared<int>(99);

// Create weak reference (count remains 1)
std::weak_ptr<int> w_ptr(s_ptr_C);

// Must 'lock' to access the object safely
if (auto locked_s = w_ptr.lock()) {
    // locked_s is a temporary shared_ptr
    *locked_s = 1;
}

// Check if resource is still valid
if (w_ptr.expired()) {
    // Resource has been deleted
}
